<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/profile-commerce-v900.php';
require_permission('account.access');
$pdo=db();$user=current_user();if(!$pdo||!$user)redirect(url('/login.php'));if(!agent_commerce_schema_ready_v800($pdo))redirect(url('/upgrade.php'));
$uid=(int)$user['id'];$profile=profile_for_user($pdo,$uid,true);$error='';$notice=trim((string)($_GET['saved']??''));
function profile_commerce_manage_redirect_v900(string $message): never{redirect(url('/profile-commerce-products.php?saved='.rawurlencode($message)));}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!verify_csrf())$error='Session expired. Please try again.';
    else try{
        $action=(string)($_POST['action']??'');
        if($action==='save_generic'){profile_commerce_save_generic_product_v900($pdo,$uid,$_POST);profile_commerce_manage_redirect_v900('Profile Commerce product saved.');}
        if($action==='publish'){profile_commerce_publish_v900($pdo,$uid,(int)($_POST['product_id']??0),$_POST);profile_commerce_manage_redirect_v900('Profile publication settings saved.');}
        throw new RuntimeException('Unknown Profile Commerce action.');
    }catch(Throwable $e){$error=$e->getMessage();}
}
$products=agent_commerce_products_for_owner_v800($pdo,$uid,200);$connections=agent_commerce_connections_v800($pdo,$uid,true);$username=profile_username_normalize((string)($profile['username']??''));
